import os,json,hashlib,subprocess,stat
from pathlib import Path
root=Path(Path('/private/tmp/scout-lg2-production-active.txt').read_text());base=json.loads((root/'baseline.json').read_text());pre=json.loads((root/'preflight.json').read_text())
def fp(p):
 p=Path(p)
 if not p.exists():return None
 s=p.lstat();assert stat.S_ISREG(s.st_mode)
 return dict(device=s.st_dev,inode=s.st_ino,size_bytes=s.st_size,allocated_bytes=s.st_blocks*512,mtime_ns=s.st_mtime_ns,ctime_ns=s.st_ctime_ns)
def sha(p):
 p=Path(p);return hashlib.sha256(p.read_bytes()).hexdigest() if p.exists() else None
services={}
for name in base['services']:
 r=subprocess.run(['launchctl','print',f'gui/{os.getuid()}/{name}'],capture_output=True,text=True);services[name]=dict(returncode=r.returncode,unloaded=r.returncode==113)
pointers={}
for parent in ['/Users/greg/.flop_scout','/Users/greg/.flop_agents/router']:
 for path,dirs,files in os.walk(parent,followlinks=False):
  dirs[:]=[d for d in dirs if d not in ['backups','.git','exports','soaks']]
  if 'current.json' in files:
   p=Path(path)/'current.json';pointers[str(p)]=dict(stat=fp(p),sha256=sha(p))
checks=dict(source_file_fingerprints_unchanged=base['source_files']=={p:fp(p) for p in base['source_files']},source_sidecar_hashes_unchanged=base['sidecar_sha256']=={p:sha(p) for p in base['sidecar_sha256']},live_projection_unchanged=base['live_projection']==fp('/Users/greg/.flop_scout/router_projection.sqlite'),inventoried_pointers_unchanged=base['pointers']==pointers,services_unchanged=base['services']==services,old_poller_unloaded=services['com.flop.scout.poll']['unloaded'],scout_runtime_unchanged=all(sha(p)==h for p,h in base['scout_code_sha256'].items()),router_runtime_unchanged=all(sha(p)==h for p,h in base['router_code_sha256'].items()),reviewed_files_unchanged=all(sha(p)==h for p,h in pre['review_sha256'].items()))
lsof=subprocess.run(['lsof','/Users/greg/.flop_scout/observer.sqlite','/Users/greg/.flop_scout/observer.sqlite-wal','/Users/greg/.flop_scout/run/service-poll.flock'],capture_output=True,text=True)
checks['no_live_db_or_poller_handles_reported']=lsof.returncode==1 and not lsof.stdout.strip()
out=dict(checks=checks,services=services,pointer_inventory=pointers,source_integrity_basis='No live SQLite connection; unchanged DB/WAL/SHM file identity,size,mtime,ctime and sidecar SHA-256. No full live DB SHA-256 claimed.',live_projection_present=base['live_projection'] is not None,temporary_root_preserved=str(root))
(root/'safety-after.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2));assert all(checks.values()),'Safety comparison changed; investigate before reporting'
